-- M8.5 performance budget: the Transactions list orders by local_date DESC, occurred_at DESC, id DESC (DESC sorts nulls
-- first). The old index had NULLS LAST and no id, so every page sorted all of the range's rows (and ran the per-row
-- subqueries on each) before its LIMIT; in this exact order the scan stops after the page. Generated by drizzle-kit.
DROP INDEX "transactions_user_id_local_date_idx";--> statement-breakpoint
CREATE INDEX "transactions_user_id_local_date_idx" ON "transactions" USING btree ("user_id","local_date" DESC NULLS FIRST,"occurred_at" DESC NULLS FIRST,"id" DESC NULLS FIRST);
